//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Largest delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for the next retry, capped without overflowing.
    pub(crate) fn next_delay(delay_ms: u64, max_delay_ms: u64) -> u64 {
        delay_ms.min(max_delay_ms)
    }

    /// Advances an already capped delay for the following retry.
    pub(crate) fn doubled_delay(delay_ms: u64, max_delay_ms: u64) -> u64 {
        delay_ms.saturating_mul(2).min(max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_is_capped_before_sleeping() {
        assert_eq!(RetryConfig::next_delay(100, 25), 25);
        assert_eq!(RetryConfig::next_delay(10, 25), 10);
    }

    #[test]
    fn delay_doubling_saturates_at_cap_without_overflow() {
        assert_eq!(
            RetryConfig::doubled_delay(u64::MAX / 2 + 1, u64::MAX),
            u64::MAX
        );
        assert_eq!(RetryConfig::doubled_delay(40, 50), 50);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero-attempt configuration is invalid according to the public contract;
    // treating it as one attempt keeps the runner from silently skipping work.
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay_ms = config.base_delay_ms;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                let delay = RetryConfig::next_delay(delay_ms, config.max_delay_ms);
                sleeper.sleep_ms(delay);
                delay_ms = RetryConfig::doubled_delay(delay, config.max_delay_ms);
            }
        }
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn retries_transient_failures_with_bounded_exponential_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn permanent_errors_are_returned_without_retrying() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 1,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still down".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still down".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn delay_schedule_saturates_at_u64_max_without_overflow() {
    let config = RetryConfig {
        max_attempts: 66,
        base_delay_ms: 1,
        max_delay_ms: u64::MAX,
    };
    let mut sleeper = FakeSleeper::default();

    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("still down".into()))
    });

    assert!(result.is_err());
    assert_eq!(sleeper.sleeps.len(), 65);
    assert_eq!(&sleeper.sleeps[0..3], &[1, 2, 4]);
    assert_eq!(&sleeper.sleeps[63..], &[u64::MAX / 2 + 1, u64::MAX]);
}
